syntax:
union UnionName {
    Type1 member1;  // First member
    Type2 member2;  // Second member, shares memory with member1
    // Implementation note: The compiler allocates memory for the largest member.
    // To manage non-POD types:
    // 1. Call destructor: member2.~Type2();  // Explicitly destroys member2
    // 2. Use placement new: new (&member1) Type1(args);  // Constructs member1 in the union's memory
};
